// ---- ai/adapters.js ----
class NullAIAdapter {
  constructor() {
    this.id = "disabled";
    this.ready = true;
  }

  async generateRoomFlavor(_input, fallback) {
    return fallback;
  }

  async generateText(_kind, _input, fallback) {
    return fallback;
  }
}
class TemplateAIAdapter extends NullAIAdapter {
  constructor() {
    super();
    this.id = "template";
  }

  async generateRoomFlavor(input, fallback) {
    const symbols = (input.symbolsPresent || []).join(" ");
    const enemies = input.contents?.monsters ? `${input.contents.monsters} hostile shapes` : "no visible enemies";
    return validateRoomFlavor({
      room_name: input.floorName || `${titleCase(input.themeLabel || input.theme)} ${input.floor}-${input.roomId}`,
      description: `The chamber answers in ${symbols || "bare stone"}. ${enemies} hold the silence. ${input.contents?.landmark || "The route is yours to read."}`,
      tone: input.dangerLevel > 4 ? "danger" : "grim",
      theme: input.theme,
      suggested_symbols: input.symbolsPresent || [],
      danger_hint: input.dangerLevel > 4 ? "Every shadow has a number behind it." : "Listen before you spend the next turn.",
      music: input.music
    }, fallback);
  }

  async generateText(kind, input, fallback) {
    return validateTextPayload({
      title: `${titleCase(kind)} Signal`,
      text: input.summary || fallback.text,
      tone: fallback.tone || "grim"
    }, fallback);
  }
}
class MockAIAdapter extends TemplateAIAdapter {
  constructor() {
    super();
    this.id = "mock";
  }

  async generateRoomFlavor(input, fallback) {
    const flavor = await super.generateRoomFlavor(input, fallback);
    return { ...flavor, description: `[mock local ai] ${flavor.description}` };
  }
}
class WebLLMAIAdapter extends NullAIAdapter {
  constructor({ profile, timeoutMs = 10000 } = {}) {
    super();
    this.id = "webllm";
    this.profile = profile;
    this.timeoutMs = timeoutMs;
    this.engine = null;
    this.ready = false;
  }

  async warm(progress = () => {}) {
    if (this.ready) return true;
    if (!("gpu" in navigator)) throw new Error("WebGPU is unavailable in this browser.");
    if (!this.profile?.modelId) throw new Error("No WebLLM model profile selected.");
    if (!this.profile?.modelLibUrl && !this.profile?.prebuilt) {
      throw new Error(`${this.profile.label || this.profile.modelId} is not yet wired to a WebLLM model_lib. Template fallback remains active.`);
    }
    progress("Importing WebLLM");
    const webllm = await import("https://esm.run/@mlc-ai/web-llm");
    progress(`Loading ${this.profile.modelId}`);
    const appConfig = this.profile.prebuilt ? undefined : {
      model_list: [{
        model: this.profile.modelUrl,
        model_id: this.profile.modelId,
        model_lib: this.profile.modelLibUrl
      }]
    };
    this.engine = await webllm.CreateMLCEngine(this.profile.modelId, {
      appConfig,
      initProgressCallback: (event) => progress(event?.text || "Loading model")
    });
    this.ready = true;
    return true;
  }

  async generateRoomFlavor(input, fallback) {
    if (!this.ready || !this.engine) return fallback;
    const prompt = PROMPTS.roomFlavor(input);
    const json = await this.generateJson(prompt);
    return validateRoomFlavor(json, fallback);
  }

  async generateText(kind, input, fallback) {
    if (!this.ready || !this.engine) return fallback;
    const json = await this.generateJson(PROMPTS.text(kind, input));
    return validateTextPayload(json, fallback);
  }

  async generateJson(prompt) {
    const completion = await withTimeout(this.engine.chat.completions.create({
      messages: [{ role: "user", content: prompt }],
      temperature: 0.7,
      max_tokens: 420
    }), this.timeoutMs);
    const text = completion?.choices?.[0]?.message?.content || "";
    const start = text.indexOf("{");
    const end = text.lastIndexOf("}");
    if (start === -1 || end <= start) throw new Error("Local model did not return JSON.");
    return JSON.parse(text.slice(start, end + 1));
  }

  async unload() {
    await this.engine?.unload?.().catch?.(() => {});
    this.engine = null;
    this.ready = false;
  }
}

function withTimeout(promise, timeoutMs) {
  return new Promise((resolve, reject) => {
    const timer = window.setTimeout(() => reject(new Error("Local AI timed out.")), timeoutMs);
    promise.then(
      (value) => {
        window.clearTimeout(timer);
        resolve(value);
      },
      (error) => {
        window.clearTimeout(timer);
        reject(error);
      }
    );
  });
}

function titleCase(value = "") {
  return String(value)
    .replace(/[_-]+/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase())
    .slice(0, 80);
}


// ---- ai/router.js ----
class AIRouter {
  constructor({ hashString, cacheStore } = {}) {
    this.hashString = hashString || simpleHash;
    this.cacheStore = cacheStore;
    this.adapter = new TemplateAIAdapter();
    this.mode = "classic";
  }

  configure(settings = {}) {
    this.mode = settings.aiMode || "classic";
    if (settings.aiNarrator === "off") {
      this.adapter?.unload?.();
      this.adapter = new NullAIAdapter();
      return;
    }
    if (settings.aiNarrator === "mock") {
      this.adapter?.unload?.();
      this.adapter = new MockAIAdapter();
      return;
    }
    if (settings.aiNarrator === "local") {
      const profile = modelProfile(this.mode);
      if (this.adapter?.id === "webllm" && this.adapter.profile?.modelId === profile.modelId) return;
      this.adapter?.unload?.();
      this.adapter = new WebLLMAIAdapter({ profile });
      return;
    }
    this.adapter?.unload?.();
    this.adapter = new TemplateAIAdapter();
  }

  async warm(progress) {
    if (typeof this.adapter.warm !== "function") return false;
    return this.adapter.warm(progress);
  }

  async generateRoomFlavor(input, fallback) {
    const key = this.cacheKey("room", input);
    const cached = this.cacheStore?.get?.(key);
    if (cached) return validateRoomFlavor(cached, fallback);
    let result = fallback;
    try {
      result = await this.adapter.generateRoomFlavor(input, fallback);
    } catch {
      result = fallback;
    }
    const validated = validateRoomFlavor(result, fallback);
    this.cacheStore?.set?.(key, validated);
    return validated;
  }

  cacheKey(kind, input) {
    const stable = JSON.stringify({
      kind,
      seed: input.seed,
      floor: input.floor,
      roomId: input.roomId,
      theme: input.theme,
      symbols: input.symbolsPresent,
      contents: input.contents,
      dangerLevel: input.dangerLevel
    });
    return `${kind}:${this.hashString(stable)}`;
  }
}
class MemoryCacheStore {
  constructor(bucket = {}) {
    this.bucket = bucket;
  }

  get(key) {
    return this.bucket[key] || null;
  }

  set(key, value) {
    this.bucket[key] = value;
  }

  clear() {
    for (const key of Object.keys(this.bucket)) delete this.bucket[key];
  }
}

function simpleHash(value) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}


// ---- core/narrator.js ----
class BrowserNarrator {
  constructor() {
    this.enabled = false;
    this.rate = 1;
    this.voiceURI = "";
    this.lastText = "";
    this.voices = [];
    this.supported = "speechSynthesis" in window && "SpeechSynthesisUtterance" in window;
    if (this.supported) {
      this.refreshVoices();
      window.speechSynthesis.addEventListener?.("voiceschanged", () => this.refreshVoices());
    }
  }

  configure(settings = {}) {
    this.enabled = Boolean(settings.voiceEnabled);
    this.rate = Number(settings.voiceRate || 1);
    this.voiceURI = settings.voiceURI || "";
    if (!this.enabled) this.stop();
  }

  refreshVoices() {
    this.voices = this.supported ? window.speechSynthesis.getVoices() : [];
    return this.voices;
  }

  speak(text, { force = false } = {}) {
    if (!this.supported || !this.enabled || !text) return;
    if (!force && text.length < 20) return;
    this.lastText = text;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.rate = Math.max(0.6, Math.min(1.4, this.rate));
    const voice = this.voices.find((candidate) => candidate.voiceURI === this.voiceURI);
    if (voice) utterance.voice = voice;
    window.speechSynthesis.speak(utterance);
  }

  repeat() {
    if (this.lastText) this.speak(this.lastText, { force: true });
  }

  pause() {
    if (this.supported) window.speechSynthesis.pause();
  }

  resume() {
    if (this.supported) window.speechSynthesis.resume();
  }

  stop() {
    if (this.supported) window.speechSynthesis.cancel();
  }
}



