    biomes: ["Soot Keep", "Banner Vault", "Chapel Armory", "Dragon Stack", "Oath Cellar", "Iron Library"],
    enemies: ["Ash Knight", "Soot Page", "Dragon Bailiff", "Oath Wraith", "False Bishop", "Helm Spider"],
