  --green: #85e89d;
  --cyan: #74d2ff;
  --amber: #ffd166;
  --rose: #ff6b7f;
  --violet: #b9a5ff;
  --blue: #6aa8ff;
  --shadow: rgba(0, 0, 0, 0.48);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

body {
  margin: 0;
  background: #090d0f;
  color: var(--ink);
}

button,
textarea,
select {
  font: inherit;
}

button,
select {
  border: 1px solid var(--line);
  background: #172126;
  color: var(--ink);
  border-radius: 6px;
}

button {
  min-height: 32px;
  padding: 0 10px;
  cursor: pointer;
}

button:disabled {
  cursor: default;
  opacity: 0.55;
}

button:hover,
button:focus-visible,
select:focus-visible,
textarea:focus-visible,
.board:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}

button.primary {
  border-color: #4e9b68;
  background: #1e5a3b;
}

h1,
h2,
h3,
p {
  margin: 0;
}

h1 {
  font-size: clamp(25px, 4.2vw, 44px);
  line-height: 0.95;
  letter-spacing: 0;
}

h2 {
  font-size: clamp(24px, 4.4vw, 54px);
  line-height: 0.98;
  max-width: 10ch;
  letter-spacing: 0;
}

h3 {
  font-size: 16px;
  line-height: 1.2;
  letter-spacing: 0;
}

.eyebrow,
.tiny {
  color: var(--muted);
  font-size: 11px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0;
  margin-bottom: 4px;
}

.rogue-shell {
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  padding: 12px;
  background:
    radial-gradient(circle at 18% 18%, rgba(116, 210, 255, 0.13), transparent 28%),
    linear-gradient(120deg, rgba(133, 232, 157, 0.08), transparent 36%),
    linear-gradient(260deg, rgba(255, 107, 127, 0.09), transparent 42%),
