  grid-template-columns: minmax(180px, auto) 1fr;
  gap: 14px;
  align-items: center;
  border: 1px solid rgba(116, 210, 255, 0.25);
  background: rgba(12, 17, 19, 0.92);
  box-shadow: 0 18px 44px var(--shadow);
  border-radius: 8px;
  padding: 10px 12px;
}

