  font: 800 26px/1 "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  box-shadow: 0 0 24px rgba(116, 210, 255, 0.12);
  animation: float 4s ease-in-out infinite;
}

.glyph-player {
  left: 22%;
  top: 28%;
  background: var(--green);
  color: #07110b;
}

.glyph-stairs {
  right: 22%;
  top: 22%;
  background: var(--cyan);
  color: #061018;
  animation-delay: -0.8s;
}

.glyph-relic {
  right: 32%;
  bottom: 24%;
  background: var(--amber);
  color: #1b1302;
  animation-delay: -1.6s;
}

.glyph-wall {
  left: 31%;
  bottom: 20%;
  background: #1a2429;
  color: #93a3aa;
  animation-delay: -2.4s;
}

.intro-terminal {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 18px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid rgba(133, 232, 157, 0.24);
  background: rgba(5, 9, 10, 0.86);
  border-radius: 6px;
  padding: 12px;
  color: var(--muted);
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  z-index: 1;
}

.intro-terminal strong {
  color: var(--green);
  font-weight: 700;
  text-align: right;
}

.play-layout {
  --log-height: 122px;
  position: relative;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr) var(--log-height);
  gap: 6px;
  overflow: hidden;
}

.board-shell,
.side-panel,
.log-dock {
  min-height: 0;
  padding: 6px;
}

.board-shell {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 5px;
  min-width: 0;
}

.board-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.board-title {
  min-width: 0;
}

.board-header h2 {
  max-width: none;
  font-size: clamp(17px, 1.9vw, 24px);
  line-height: 1.05;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.board-command-strip {
  display: flex;
  flex: 1 1 auto;
  justify-content: flex-end;
  align-items: center;
  gap: 5px;
  min-width: 0;
}

.board-command-strip .turn-chip {
  flex: 0 0 auto;
  min-height: 28px;
  padding: 5px 8px;
  font-size: 13px;
}

.board-frame {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 0;
  border: 1px solid #26343a;
  border-radius: 8px;
  background: #070b0d;
  overflow: hidden;
}

.board-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, transparent 0%, rgba(116, 210, 255, 0.06) 50%, transparent 100%);
  mix-blend-mode: screen;
  animation: scan 6s linear infinite;
}

.board {
  --cols: 23;
  display: grid;
  grid-template-columns: repeat(var(--cols), minmax(14px, 1fr));
  gap: 2px;
  width: 100%;
  max-width: 100%;
  aspect-ratio: 23 / 15;
  padding: 4px;
  overflow: hidden;
}

.board.board-hit {
  animation: damage-shake 220ms ease both;
}

.tile {
  display: grid;
  place-items: center;
  min-width: 0;
  min-height: 0;
  aspect-ratio: 1;
  border-radius: 4px;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  font-size: clamp(10px, 1.35vw, 18px);
  line-height: 1;
  color: #77868b;
  background: #10171a;
  transform: translateZ(0);
}

.tile.reveal {
  opacity: 0.38;
  animation: tile-in 420ms ease forwards;
  animation-delay: var(--delay, 0ms);
}

.tile.wall {
  color: #506068;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.04), transparent),
    #1b252a;
}

.tile.floor {
  background: #0f1518;
}

.tile.seen,
.tile.unseen {
  color: #3f4d52;
  background: #080c0e;
}

.tile.unseen {
  color: transparent;
}

.tile.door,
.tile.door-open {
  color: #180f01;
  background: var(--amber);
  font-weight: 800;
}

.tile.door-open {
  color: #9aa8a8;
  background: #12191c;
}

.tile.trap {
  color: #24060a;
  background: var(--rose);
  font-weight: 800;
}

.tile.liquid {
  color: #061018;
  background: var(--cyan);
  font-weight: 800;
}

.tile.player {
  color: #07110b;
  background: var(--green);
  font-weight: 800;
  box-shadow: 0 0 18px rgba(133, 232, 157, 0.28);
  animation: player-breathe 1.6s ease-in-out infinite;
}

.tile.enemy {
  color: #21070d;
  background: var(--rose);
  font-weight: 800;
  box-shadow: 0 0 18px rgba(255, 107, 127, 0.22);
  animation: enemy-pulse 1.9s ease-in-out infinite;
}

.tile.item {
  color: #1a1200;
  background: var(--amber);
  font-weight: 800;
  animation: item-glow 2.1s ease-in-out infinite;
}

.tile.stairs {
  color: #061018;
  background: var(--cyan);
  font-weight: 800;
  animation: stair-glow 1.7s ease-in-out infinite;
}

.tile.landmark {
  color: #100d24;
  background: var(--violet);
  font-weight: 800;
}

.tile.fx-step {
  animation: step-pop 180ms ease both;
}

.tile.fx-hit {
  animation: hit-flash 260ms ease both;
}

.tile.fx-pickup {
  animation: pickup-flash 340ms ease both;
}

.tile.fx-bump {
  animation: bump-flash 180ms ease both;
}

.action-row {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 5px;
  min-width: 0;
}

.action-row button {
  min-width: 30px;
  min-height: 28px;
  padding: 0 8px;
  font-size: 12px;
}

.side-panel {
  position: absolute;
  top: 52px;
  right: 0;
  bottom: calc(var(--log-height) + 6px);
  z-index: 6;
  width: min(420px, calc(100% - 24px));
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 8px;
  min-width: 0;
  overflow: hidden;
  transform: translateX(0);
  transition: transform 180ms ease, opacity 180ms ease;
  box-shadow: -18px 0 48px rgba(0, 0, 0, 0.42);
}

.play-layout.is-panel-collapsed .side-panel {
  opacity: 0.98;
  pointer-events: none;
  transform: translateX(calc(100% + 10px));
}

.panel-toggle {
  position: relative;
  z-index: 9;
  flex: 0 0 auto;
  min-height: 28px;
  padding: 0 9px;
  border-color: rgba(133, 232, 157, 0.5);
  background: #1e5a3b;
  color: var(--ink);
  font-weight: 800;
}

.panel-toggle[aria-expanded="true"] {
  border-color: rgba(116, 210, 255, 0.62);
  background: #12232c;
  color: var(--cyan);
}

.panel-tabs {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
}

.panel-tabs button {
  min-height: 28px;
  padding: 0 6px;
  font-size: 12px;
}

.panel-pages {
  min-height: 0;
  display: grid;
}

.panel-section {
  min-height: 0;
  overflow: hidden;
  border: 1px solid #2a3940;
  background: var(--panel-2);
  border-radius: 6px;
  padding: 9px;
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.panel-page {
  display: none;
}

.panel-page.is-active {
  display: flex;
}

.hero-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px 8px;
  color: #d9e0df;
  font-size: 12px;
}

.hero-grid span {
  display: flex;
  justify-content: space-between;
  gap: 6px;
}

.quest-section p:last-child {
  color: #d9e0df;
  line-height: 1.32;
  overflow: hidden;
}

.inventory {
  display: grid;
  gap: 6px;
  align-content: start;
  overflow: auto;
  scrollbar-width: thin;
}

.inventory-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  border: 1px solid rgba(116, 210, 255, 0.14);
  background: rgba(7, 11, 13, 0.38);
  border-radius: 6px;
  padding: 6px;
}

.inventory-item.equipped {
  border-color: rgba(133, 232, 157, 0.45);
}

.inventory-item strong,
.inventory-item span,
.empty-pack {
  display: block;
  min-width: 0;
}

.inventory-item strong {
  color: #d9e0df;
  font-size: 12px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.inventory-item span,
.empty-pack {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.2;
}

.inventory-item button {
  min-height: 26px;
  padding: 0 8px;
  font-size: 12px;
}

.director-grid {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  align-items: end;
}

.director-grid strong {
  align-self: center;
  color: var(--cyan);
  font-size: 13px;
}

label {
  display: grid;
  gap: 4px;
  color: var(--muted);
  font-size: 11px;
}

select,
input[type="range"] {
  min-height: 36px;
  padding: 0 10px;
}

fieldset {
  min-width: 0;
  border: 1px solid rgba(116, 210, 255, 0.16);
  border-radius: 6px;
  padding: 8px;
}

legend {
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
  padding: 0 4px;
}

.notice {
  color: #d9e0df;
  font-size: 13px;
  line-height: 1.35;
}

.settings-stack {
  min-height: 0;
  display: grid;
  gap: 8px;
  overflow: auto;
  scrollbar-width: thin;
}

.settings-stack label {
  margin-top: 6px;
}

.check-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.settings-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
}

.settings-actions button,
[data-prepare-local-ai] {
  min-height: 28px;
  padding: 0 8px;
  font-size: 12px;
}

.log-dock {
  grid-column: 1 / -1;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 5px;
  padding: 8px 10px 10px;
  background: rgba(7, 11, 13, 0.96);
}

.log-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--muted);
  font-size: 11px;
}

.log-header .eyebrow {
  margin: 0;
}

.log {
  min-height: 0;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-auto-rows: min-content;
  column-gap: 16px;
  overflow: hidden;
  list-style: none;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
}

.log li {
  min-width: 0;
  margin: 0;
  padding: 1px 0;
  color: #d8e1df;
  line-height: 1.25;
  font-size: clamp(11px, 1.1vw, 12px);
  white-space: normal;
  overflow: visible;
  overflow-wrap: anywhere;
  text-overflow: clip;
}

.log li:first-child {
  color: var(--green);
  animation: log-in 180ms ease both;
}

@keyframes scan {
  from {
    transform: translateY(-100%);
  }
  to {
    transform: translateY(100%);
  }
}

@keyframes rotate {
  to {
    transform: rotate(360deg);
  }
}

@keyframes float {
  50% {
    transform: translateY(-10px);
  }
}

@keyframes tile-in {
  from {
    opacity: 0.38;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes player-breathe {
  50% {
    transform: scale(1.06);
    box-shadow: 0 0 24px rgba(133, 232, 157, 0.42);
  }
}

@keyframes enemy-pulse {
  50% {
    transform: scale(1.05);
  }
}

@keyframes item-glow {
  50% {
    box-shadow: 0 0 16px rgba(255, 209, 102, 0.34);
  }
}

@keyframes stair-glow {
  50% {
    box-shadow: 0 0 20px rgba(116, 210, 255, 0.4);
  }
}

@keyframes step-pop {
  50% {
    transform: scale(1.16);
  }
}

@keyframes hit-flash {
  45% {
    transform: scale(1.2);
    background: #fff0c2;
    color: #1c0900;
  }
}

@keyframes pickup-flash {
  45% {
    transform: scale(1.22);
    background: #ffffff;
    color: #111;
  }
}

@keyframes bump-flash {
  50% {
    background: #5d2c37;
  }
}

@keyframes damage-shake {
  20% {
    transform: translateX(-5px);
  }
  40% {
    transform: translateX(5px);
  }
  60% {
    transform: translateX(-3px);
  }
  80% {
    transform: translateX(3px);
  }
}

@keyframes log-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 610px) {
  .rogue-shell {
    padding: 8px;
  }

  .game-hud {
    grid-template-columns: 1fr;
    min-height: 0;
  }

  .hud-readout {
    justify-content: stretch;
    flex-wrap: wrap;
  }

  .hud-stat {
    flex: 1 1 72px;
  }

  .intro-screen,
  .play-layout {
    grid-template-columns: 1fr;
  }

  .intro-screen {
    grid-template-rows: minmax(0, 1fr) minmax(150px, 0.6fr);
  }

  .play-layout {
    --log-height: 116px;
    grid-template-rows: minmax(0, 1fr) var(--log-height);
  }

  .side-panel,
  .log-dock {
    grid-column: 1;
  }

  .board {
    width: min(100%, calc((100vh - 520px) * 1.53));
    padding: 5px;
    gap: 2px;
  }

  .side-panel {
    top: 78px;
    bottom: calc(var(--log-height) + 8px);
    width: min(360px, calc(100% - 18px));
    grid-template-rows: auto minmax(0, 1fr);
  }

  .director-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 610px) {
  .game-hud {
    gap: 7px;
    padding: 8px;
  }

  .brand-block strong {
    font-size: 13px;
  }

  .hud-readout {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 6px;
  }

  .hud-stat,
  .engine-pill {
    min-width: 0;
    padding: 7px 8px;
  }

  .engine-pill {
    grid-column: 1 / span 2;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  [data-music-toggle] {
    min-width: 0;
    padding: 0 8px;
  }

  .intro-art {
    display: none;
  }

  .intro-screen {
    grid-template-rows: 1fr;
  }

  .play-layout {
    --log-height: 118px;
    grid-template-rows: minmax(0, 1fr) var(--log-height);
    gap: 8px;
  }

  .board-shell {
    padding: 8px;
    gap: 7px;
  }

  .board-header h2 {
    font-size: 16px;
  }

  .board-header {
    align-items: stretch;
  }

  .board-command-strip {
    flex: 0 1 auto;
    flex-direction: column;
    align-items: end;
    gap: 5px;
  }

  .board {
    width: min(100%, calc((100vh - 535px) * 1.53));
  }

  .action-row {
    flex-wrap: wrap;
    gap: 4px;
  }

  .action-row button {
    min-width: 28px;
    padding: 0 6px;
  }

  .side-panel {
    top: 78px;
    bottom: calc(var(--log-height) + 8px);
    width: min(360px, calc(100% - 18px));
    grid-template-rows: auto minmax(0, 1fr);
    gap: 6px;
  }

  .panel-section {
    padding: 7px;
    gap: 4px;
  }

  .quest-section p:last-child,
  .director-section .tiny,
  label span {
    display: none;
  }

  .log {
    grid-template-columns: 1fr;
  }
}
